// hk-data.js — 홍콩 여행 앱(2026-11) 공유 데이터. base.html(=index.html, 사진만 파일 경로) 의 데이터 상수를 값 그대로 떼어낸 것.
// 생성: qa/make_base2.cjs (base.html 을 읽어 만든다. 손으로 고치지 말고 스크립트를 고친다)
//
// 쓰는 법
//   <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
//   <script src="hk-data.js"></script>      ← 이 파일. 클래식 스크립트, 모든 이름이 전역 const (window 속성은 아님: typeof ST 로 확인)
//   <script> …안별 UI… </script>            ← 그 다음에 로드. 아래 이름을 그대로 읽는다
//   세 안(a/b/c.html)이 이 파일 하나를 공유한다. 이 파일은 고치지 않는다 — 새 상수가 필요하면 자기 html 안에 둔다.
//   값이 바뀌어야 하면(일정 확정 등) 오케스트레이터가 base.html → make_base2.cjs 로 다시 만든다.
//
// 이름 바꾼 것 (base.html 에서 이름이 겹치던 둘)
//   base.html 388행  const DAYS  (견적 귀국일 선택 [{d,lab,prev}])          → 그대로 DAYS
//   base.html 693행  const DAYS  (일정 d1~d4, IIFE 안)                        → TRIP_DAYS   (base2.html 은 IIFE 안에서 const DAYS=TRIP_DAYS; 로 받음)
//   base.html 385행  const F     (항공 운임표, 전역)                           → 그대로 F
//   base.html 1148행 const F     (내 정보 입력 칸 16개, IIFE 안)               → ME_FIELDS   (base2.html 은 IIFE 안에서 const F=ME_FIELDS; 로 받음)
//   그 외 이름은 base.html 과 같다. 소문자 이름(paths·tabs·routes)도 원본 그대로.
//
// 값이 base.html 과 다른 곳 — 한 곳
//   AINFO.np: base.html 448행이 447행 AINFO 를 다시 덮어쓰던 것을 제거했다. 그래서 np.one 은
//   «조용한 로컬 동네 — 하버뷰 호텔을 비교적 싸게»(447행 값), np.good[0] 도 447행 값(«하버뷰 5성이 침사추이 5성보다 쌈(…)»).
//   나머지 네 동네는 447·448행이 같은 문구라 차이 없다.
//
// 공통 키
//   동네키 k ∈ 'tst'(침사추이) 'cen'(센트럴·셩완) 'cwb'(코즈웨이베이·완차이) 'np'(노스포인트) 'mk'(몽콕·야우마테이)
//     — AREAS·ST[1]·AINFO·REPORT_PHOTOS·PINS·HP·COL·routes·TripState.hotel.area 가 모두 이 다섯 키.
//   정류장키 stopKey = TRIP_DAYS[*].stops[*][0] ('hkia' 'kowloon' 'hotel' 'ckm' 'aos' 'ferry' …) — GUIDE·VIEW·PHOTO·IG_AT·TIP_AT 의 키.
//   준비키 prepId = PREP[*].items[*][0] ('p-octo' …) — IG_AT·TIP_AT 의 키, localStorage hk-check 의 키.
//   꿀팁키 '묶음:제목' = TIPS[i][0] + ':' + TIPS[i][1][j][0] — TIP_AT 의 값, IG_AT 의 'tip:묶음' 키.
//   숙소 ID = ST[i][0] (한글 이름 그대로) — localStorage hk-quote-web3.stay, data-detail, HP 의 [0].
//   금액은 KRW 정수. HKD 표기가 있는 것만 홍콩달러(MEALS·SNACK·EXTRAS 설명문).
//
// 스키마 (배열은 인덱스 의미, 개수는 생성 시점 실측)
//   F          {'출발-귀국'(24-28|24-29|23-28|23-29): {O, R, P}}  항공 운임표 — 구입 확정 전 유물. 코드는 O 중 UO 12:25 와 R 중 16:40 만 쓰고 가격은 window.FWL 로 덮음.
//                O[i] = [항공사코드, 출발HH:MM, 도착HH:MM, 왕복기준가KRW, 같은항공사귀국합산기준가KRW|null]
//                R[i] = [항공사코드, 출발, 도착, 가산액KRW]            가격 = O[4] + R[3]
//                P[i] = [O의 인덱스, 항공사코드, 출발, 도착, 왕복총액KRW]
//   AL         {항공사코드: [한글이름, 저가항공 1|0]}  9개
//   DEPS       [{d:24, lab:'11/24 (화)', prev:'11/23 (월)'}]  출발일 선택지 1개
//   DAYS       [{d:28, lab:'11/28 (토)', prev:'11/27 (금)'}]  귀국일 선택지 1개 (견적용 — 일정은 TRIP_DAYS)
//   AREAS      [{k:동네키, nm:표시명, c:색}]  5개
//   TYPES      [{k:'all'|'hotel'|'airbnb', nm}]  3개
//   SITES      [[표시명, 한글명, ID키('ag'|'tr'|'ex')|null, (id, 체크인YYYY-MM-DD, 체크아웃)=>URL | null]]  7개 — 함수가 들어 있어 JSON 아님
//   MON        ['Jan',…,'Dec']  12개. base.html 에서 미사용
//   ST         숙소 48개(호텔 38·에어비앤비 10). 각 16칸
//                [0 이름(=ID), 1 동네키, 2 'hotel'|'airbnb', 3 등급/구성('4성' '집 전체 · 퀸 1' '연주 후보'), 4 평점 number|null,
//                 5 리뷰수 문자열('465' '3.0천'), 6 1박 KRW(에어비앤비는 4박÷4), 7 메모, 8 lat, 9 lng,
//                 10 사진 경로 'img/stay/<파일>.jpg'(360px 썸네일, 저장소에 untracked), 11 에어비앤비 room id|null, 12 영문명|null,
//                 13 {사이트명: 1박 KRW}|null, 14 {ag, tr, ex: 사이트별 호텔ID}|null, 15 [최소㎡, 최대㎡]|null]
//   HKD        185 (원/HKD)
//   EXTRAS     [[키, 이름, 설명, 단가KRW, 'trip'(여행 1회)|'day'(1인 1일), 기본켬 1|0]]  8개 (disney ael food move peak sim ins fine)
//                주의: 원본 render() 가 food 행의 [2]·[3] 을 매번 덮어쓴다(끼니 선택 반영). 새 안도 밥값은 계산해서 쓰고 이 배열을 freeze 하지 않는다.
//   MEALS      {b|l|d: [라벨, [[키, 이름, HKD]]]}  아침 3·점심 3·저녁 3
//   SNACK      60 (HKD/일 — 밀크티·에그타르트)
//   AINFO      {동네키: {one 한 줄, mood 분위기, good[], bad[], air 공항 접근, near[] 가까운 곳, who 추천 대상, ph[2] 사진 경로 'img/ainfo/NN.jpg', cr[2] 사진 출처}}  5개
//                ph·cr 는 지금 화면에서 안 쓴다(REPORT_PHOTOS 가 대신). ph 를 쓰면 cr 저작자 표기 필요.
//   REPORT_PHOTOS {동네키: ['img/area/….jpg', '….jpg']}  동네 리포트 사진 2장씩(560px급, 저장소 커밋됨, 출처는 base.html 379행)
//   BAG        118000 (위탁 20kg 2구간, 미사용)   BUY 265000 구매선 KRW   DL '2026-11-17' 마감
//   LYW        작년 추세 26주치 KRW(26주 전 → 1주 전)   DEP '2026-11-24' 출발일   SER [{d:28|29, lab, c}] 그래프 두 선
//   PINS       {동네키: [[이름, lat, lng]]}  리포트 지도 회색 점(같은 이름 중복 행 있음)
//   HP         {동네키: [[이름, lat, lng, 1박KRW]]}  ST 의 사본 48개 — 새 안은 ST 에서 파생하면 됨
//   COL        {동네키: 색}  미사용
//   TRIP_DAYS  {d1|d2|d3|d4: {label, sub, desc, stops:[stop]}}  d1 도착(24일) · d2 센트럴(26) · d3 구룡(27) · d4 홍콩섬(28, 일요일 귀국용 — 지금은 yick 만 씀)
//                stop = [0 key, 1 time('09:00'|'저녁'|'선택'…), 2 ko, 3 zh, 4 en, 5 addrZh, 6 lat, 7 lng, 8 memo, 9 tag(''|'film'|'night'|'must'|'gone'|'opt')]
//                25일 디즈니·28일 귀국은 상수가 아니라 코드(disney()·RETURN)가 만든다.
//   PREP       [{grp, items:[[0 id('p-…'), 1 이름, 2 언제, 3 한 줄 설명, 4 steps[], 5 warn]]}]  3묶음 15개
//   NOPE       [[이름, 이유]]  홍콩에서 안 되는 앱 4개
//   DEPART     [{t:단계 제목, steps[]}]  출국 5단계 (원본은 i===1 뒤에 6100 시간표 카드, i===4 에서 '무료 셔틀' 줄 제거)
//   BUS_OUT / BUS_RET  문자열 5개씩 — 6100 공항버스 시각(가는 날·오는 날)
//   RETURN     문자열 8개 — 귀국 절차
//   TIPS       [[묶음, [[제목, 본문]]]]  8묶음 40줄
//   paths      {quote schedule prep talk me check star: svg path d}  탭바 아이콘 7개 [UI 전용]
//   tabs       [['quote','견적·예약'],['prep','준비'],['schedule','일정'],['talk','회화'],['me','내 정보']]
//   TALK       [[묶음, 시기, [[ko, 보여줄 말(광둥어 한자 또는 영어), 한글 발음, 영어]]]]  11묶음 82문장
//   routes     {동네키: 디즈니 가는 길 한 줄}  5개
//   VIEW       {stopKey: 기상청 카메라 라벨}  야경 장소 5개   HKO_CAM 기상청 실시간 카메라 URL
//   GUIDE      {stopKey: {go?, check?[], apps?:[[라벨, url]]}}  다음 갈 곳 안내 — 첫날 6곳만 채워짐
//   SKIP_ICON LINK_ICON KSVG{plane train bed boat moon star pin} IG_ICON TIP_ICON MORE_ICON ACT_GO ACT_TAXI ACT_MEMO ACT_LIST
//              [UI 전용] 인라인 SVG 문자열. KSVG 는 <svg> 안쪽만(바깥 svg 는 코드가 감쌈), 나머지는 <svg …></svg> 전체. MORE_ICON 미사용.
//   TAGNM      {film:'영화', night:'야경', gone:'없어짐', opt:'선택', must:'필수'}  stop[9] 표시명
//   PHOTO      {stopKey: 'img/area 파일명(확장자 없음)'}  10개 — 'img/area/' + 값 + '.jpg'
//   FLIGHTS    {'24': […], 'return': […]}  각 [출발지, 코드, 도착지, 코드, 편명·항공사, 출발시각, 출발터미널, 도착시각, 도착터미널, 소요]
//   IG         [[0 번호, 1 계정, 2 경로('reel/…'|'p/…'), 3 제목, 4 목적, 5 장소]]  38개 — 영상은 'ig/<경로 뒷부분>.mp4'(36번은 파일 없음 → 임베드 폴백)
//   IG_AT      {stopKey | prepId | 'tip:묶음': [IG 번호…]}
//   TIP_AT     {stopKey | prepId: ['묶음:제목'…]}
//   APP        'hk' — Supabase my_info·trip_marks·보관함 경로의 앱 구분값
//   ME_FIELDS  내 정보 입력 칸 16개 (#me_<key>, my_info.data 의 키)
//   SLOTS      [[slot, 라벨]]  서류 보관함 8칸
//   KINDS      ['hk-check','hk-fav','hk-note'] — Supabase trip_marks 와 동기화하는 localStorage 키

